// def tparam_gen[T: Shape](x: T) -> Iterator[bool]:
//     # generator: a type-parameter walrus is tested by its value's type
//     if isinstance(y := same(x), Square):  # tpyc: ok
//         yield True                                                      # -> S_RESUME_0
//     else:
//         yield False                                                     # -> S_RESUME_1
//     yield isinstance(z := same(x), Square)  # tpyc: ok                  # -> S_RESUME_2
//     w = same(x)
//     yield isinstance(w, Square)  # tpyc: ok                             # -> S_RESUME_3
template <typename T>
std::expected<bool, ::tpy::StopIteration> __gen_tparam_gen<T>::__next__() {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_DONE;  // until a yield sets where to resume
        if (({ (void)(y.emplace(::tpyapp::main::same<T>(x))); ::tpy::isinstance_static<Square, T>(); })) {
            __state = S_RESUME_0;
            return true;
        } else {
            __state = S_RESUME_1;
            return false;
        }
    }
    case S_RESUME_2: {  // after: yield isinstance(z := same(x), Square)  # tpyc: ok
        w.emplace(::tpyapp::main::same<T>(x));
        __state = S_RESUME_3;
        return ::tpy::isinstance_static<Square, T>();
    }
    case S_RESUME_3: {  // after: yield isinstance(w, Square)  # tpyc: ok
        __state = S_DONE;
        return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    case S_RESUME_0:  // after: yield True
    case S_RESUME_1:  // after: yield False
    case S_JOIN_0: {
        __state = S_RESUME_2;
        return ({ (void)(z.emplace(::tpyapp::main::same<T>(x))); ::tpy::isinstance_static<Square, T>(); });
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}


